JSON.stringify((function(){
    const R=(e)=>{const r=e.getBoundingClientRect();return {t:Math.round(r.top),b:Math.round(r.bottom),h:Math.round(r.height),w:Math.round(r.width)};};
    const tb=document.querySelector('[data-im="board-toolbar"]');
    const out={toolbar:R(tb), children:[]};
    for(const c of tb.children){ out.children.push({cls:c.className, ...R(c), kids:[...c.children].map(k=>({cls:k.className, ...R(k)}))}); }
    return out;
  })())
